-- Put back the subcommands of /topic and /personality.
-- The command editor page saved these built-ins as flat text boxes (it has no subcommands),
-- so /personality find had no search box. updateCommand now refuses that; this repairs the rows.

UPDATE commands SET options = '[{"name":"new","description":"Get a random topic of conversation","type":1,"options":[{"name":"kind","description":"What sort of topic (any if blank)","type":3,"required":false,"choices":[{"name":"Silly debates","value":"debate"},{"name":"Would you rather","value":"rather"},{"name":"Hypotheticals","value":"what_if"},{"name":"Food","value":"food"},{"name":"Everyday life","value":"life"}]}]},{"name":"settings","description":"Server options for /topic (Manage Server only)","type":1,"options":[{"name":"set_voice_status","description":"In a voice channel''s chat, also set the voice channel status to the topic","type":5,"required":false},{"name":"custom_only","description":"Use only this server''s own topics (once it has some)","type":5,"required":false}]},{"name":"add","description":"Add a topic to this server''s own list (Manage Server only)","type":1,"options":[{"name":"text","description":"The topic, up to 200 characters","type":3,"required":true,"max_length":200}]},{"name":"remove","description":"Remove a topic from this server''s list (Manage Server only)","type":1,"options":[{"name":"number","description":"Its number from /topic list","type":4,"required":true,"min_value":1}]},{"name":"list","description":"Show this server''s own topics (Manage Server only)","type":1},{"name":"set","description":"Set a voice channel''s topic, even if you are not in it (Manage Server only)","type":1,"options":[{"name":"channel","description":"The voice channel","type":7,"required":true,"channel_types":[2,13]},{"name":"text","description":"The topic (a random one if blank)","type":3,"required":false,"max_length":200}]},{"name":"clear","description":"Clear a voice channel''s topic (Manage Server only)","type":1,"options":[{"name":"channel","description":"The voice channel","type":7,"required":true,"channel_types":[2,13]}]}]'
WHERE guild_id = '__built_in__' AND name = 'topic';

UPDATE commands SET options = '[{"name":"list","description":"See the personality tests this server shows","type":1,"options":[{"name":"category","description":"Only one kind (all of them if blank)","type":3,"required":false,"choices":[{"name":"Type & temperament","value":"type"},{"name":"Big Five & traits","value":"traits"},{"name":"Autism & neurodiversity","value":"neuro"},{"name":"Relationships & intimacy","value":"relationships"},{"name":"Dark traits","value":"dark"},{"name":"Career & strengths","value":"career"},{"name":"Values & politics","value":"values"},{"name":"Just for fun","value":"fun"},{"name":"More tests","value":"hubs"}]}]},{"name":"find","description":"Find a test by name or topic, like autism or enneagram","type":1,"options":[{"name":"search","description":"A name or topic","type":3,"required":true,"max_length":60}]},{"name":"hide","description":"Stop showing a test in this server (Manage Server only)","type":1,"options":[{"name":"test","description":"The test''s name","type":3,"required":true,"max_length":60}]},{"name":"show","description":"Show a hidden test again (Manage Server only)","type":1,"options":[{"name":"test","description":"The test''s name","type":3,"required":true,"max_length":60}]},{"name":"reset","description":"Show every built-in test again (Manage Server only)","type":1},{"name":"add","description":"Add your own link to the list (Manage Server only)","type":1,"options":[{"name":"name","description":"What it is called","type":3,"required":true,"max_length":60},{"name":"link","description":"The https link","type":3,"required":true,"max_length":300},{"name":"category","description":"Where it goes in the list","type":3,"required":false,"choices":[{"name":"Type & temperament","value":"type"},{"name":"Big Five & traits","value":"traits"},{"name":"Autism & neurodiversity","value":"neuro"},{"name":"Relationships & intimacy","value":"relationships"},{"name":"Dark traits","value":"dark"},{"name":"Career & strengths","value":"career"},{"name":"Values & politics","value":"values"},{"name":"Just for fun","value":"fun"},{"name":"More tests","value":"hubs"}]},{"name":"note","description":"A short note","type":3,"required":false,"max_length":120}]},{"name":"remove","description":"Remove one of your own links (Manage Server only)","type":1,"options":[{"name":"number","description":"Its number from /personality manage","type":4,"required":true,"min_value":1}]},{"name":"manage","description":"Show what is hidden and your own links (Manage Server only)","type":1}]'
WHERE guild_id = '__built_in__' AND name = 'personality';
